/**
 * Knowledge Hub Service Worker
 * Provides offline functionality and performance optimizations
 */

const CACHE_NAME = 'knowledge-hub-v1.0.0';
const STATIC_CACHE = 'knowledge-hub-static-v1.0.0';
const DYNAMIC_CACHE = 'knowledge-hub-dynamic-v1.0.0';

// Assets to cache immediately
const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/styles.css',
  '/scripts.js',
  '/manifest.json',
  // Add other critical assets
];

// Assets to cache on first access
const DYNAMIC_ASSETS = [
  '/BOOK/',
  '/COURSES/',
  '/THOUGHTS/',
  '/PROJECTS/',
];

/**
 * Install event - cache critical assets
 */
self.addEventListener('install', (event) => {
  console.log('[SW] Installing service worker...');

  event.waitUntil(
    caches.open(STATIC_CACHE)
      .then((cache) => {
        console.log('[SW] Caching static assets');
        return cache.addAll(STATIC_ASSETS);
      })
      .then(() => {
        console.log('[SW] Static assets cached successfully');
        return self.skipWaiting();
      })
      .catch((error) => {
        console.error('[SW] Failed to cache static assets:', error);
      })
  );
});

/**
 * Activate event - clean up old caches
 */
self.addEventListener('activate', (event) => {
  console.log('[SW] Activating service worker...');

  event.waitUntil(
    caches.keys()
      .then((cacheNames) => {
        return Promise.all(
          cacheNames.map((cacheName) => {
            if (cacheName !== STATIC_CACHE && 
                cacheName !== DYNAMIC_CACHE &&
                cacheName.startsWith('knowledge-hub-')) {
              console.log('[SW] Deleting old cache:', cacheName);
              return caches.delete(cacheName);
            }
          })
        );
      })
      .then(() => {
        console.log('[SW] Service worker activated');
        return self.clients.claim();
      })
  );
});

/**
 * Fetch event - serve cached content when offline
 */
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Skip non-GET requests
  if (request.method !== 'GET') {
    return;
  }

  // Skip external requests
  if (url.origin !== location.origin) {
    return;
  }

  event.respondWith(
    caches.match(request)
      .then((cachedResponse) => {
        // Return cached version if available
        if (cachedResponse) {
          console.log('[SW] Serving from cache:', request.url);

          // Update cache in background for HTML files
          if (request.headers.get('accept')?.includes('text/html')) {
            fetchAndCache(request);
          }

          return cachedResponse;
        }

        // Fetch from network and cache the response
        return fetchAndCache(request);
      })
      .catch(() => {
        // Fallback for offline scenarios
        if (request.headers.get('accept')?.includes('text/html')) {
          return caches.match('/index.html');
        }

        // Return a basic response for other resources
        return new Response('Offline', {
          status: 200,
          headers: { 'Content-Type': 'text/plain' }
        });
      })
  );
});

/**
 * Fetch from network and cache the response
 */
async function fetchAndCache(request) {
  try {
    const response = await fetch(request);

    // Only cache successful responses
    if (!response || response.status !== 200 || response.type !== 'basic') {
      return response;
    }

    // Clone response for caching
    const responseToCache = response.clone();
    const url = new URL(request.url);

    // Determine cache type
    const isStatic = STATIC_ASSETS.some(asset => url.pathname.endsWith(asset));
    const cacheName = isStatic ? STATIC_CACHE : DYNAMIC_CACHE;

    // Cache the response
    caches.open(cacheName)
      .then((cache) => {
        console.log('[SW] Caching:', request.url);
        cache.put(request, responseToCache);
      })
      .catch((error) => {
        console.error('[SW] Failed to cache:', request.url, error);
      });

    return response;

  } catch (error) {
    console.error('[SW] Fetch failed:', request.url, error);
    throw error;
  }
}

/**
 * Background sync for offline actions
 */
self.addEventListener('sync', (event) => {
  console.log('[SW] Background sync:', event.tag);

  if (event.tag === 'search-sync') {
    event.waitUntil(syncSearchQueries());
  }
});

/**
 * Sync search queries when back online
 */
async function syncSearchQueries() {
  try {
    // Get pending search queries from IndexedDB
    const pendingQueries = await getPendingSearchQueries();

    for (const query of pendingQueries) {
      try {
        // Attempt to fetch search results
        const response = await fetch(`/search?q=${encodeURIComponent(query.term)}`);

        if (response.ok) {
          // Store results and mark query as synced
          await storeSearchResults(query.id, await response.json());
          await markQueryAsSynced(query.id);

          // Notify clients about updated results
          self.clients.matchAll().then(clients => {
            clients.forEach(client => {
              client.postMessage({
                type: 'search-synced',
                queryId: query.id,
                term: query.term
              });
            });
          });
        }
      } catch (error) {
        console.error('[SW] Failed to sync search query:', query.term, error);
      }
    }
  } catch (error) {
    console.error('[SW] Background sync failed:', error);
  }
}

/**
 * Push notification handling
 */
self.addEventListener('push', (event) => {
  console.log('[SW] Push notification received');

  const options = {
    body: 'New content available!',
    icon: '/icons/icon-192.png',
    badge: '/icons/badge-72.png',
    vibrate: [100, 50, 100],
    data: {
      dateOfArrival: Date.now(),
      primaryKey: 1
    },
    actions: [
      {
        action: 'explore',
        title: 'Explore',
        icon: '/icons/checkmark.png'
      },
      {
        action: 'close',
        title: 'Close',
        icon: '/icons/xmark.png'
      }
    ]
  };

  if (event.data) {
    const data = event.data.json();
    options.title = data.title || 'Knowledge Hub';
    options.body = data.body || options.body;
    options.data = { ...options.data, ...data };
  }

  event.waitUntil(
    self.registration.showNotification('Knowledge Hub', options)
  );
});

/**
 * Notification click handling
 */
self.addEventListener('notificationclick', (event) => {
  console.log('[SW] Notification clicked:', event.action);

  event.notification.close();

  if (event.action === 'explore') {
    // Open the app
    event.waitUntil(
      clients.openWindow('/')
    );
  }
});

/**
 * Message handling from clients
 */
self.addEventListener('message', (event) => {
  const { type, data } = event.data;

  switch (type) {
    case 'SKIP_WAITING':
      self.skipWaiting();
      break;

    case 'GET_VERSION':
      event.ports[0].postMessage({ version: CACHE_NAME });
      break;

    case 'CLEAR_CACHE':
      event.waitUntil(
        caches.keys().then(cacheNames => {
          return Promise.all(
            cacheNames.map(cacheName => caches.delete(cacheName))
          );
        })
      );
      break;

    default:
      console.log('[SW] Unknown message type:', type);
  }
});

/**
 * Error handling
 */
self.addEventListener('error', (error) => {
  console.error('[SW] Service worker error:', error);
});

self.addEventListener('unhandledrejection', (event) => {
  console.error('[SW] Unhandled promise rejection:', event.reason);
});

