     * Fetch projects for a category
     */
    async fetchCategoryProjects(categoryId) {
        // In a real implementation, this would fetch from an API or filesystem
        // For now, we'll generate mock data based on the category structure

        const category = this.categories.get(categoryId);
        if (!category) return [];

        const mockProjects = [];

        for (const subcategory of category.subcategories) {
            // Generate 2-4 projects per subcategory
            const projectCount = Math.floor(Math.random() * 3) + 2;

            for (let i = 0; i < projectCount; i++) {
                mockProjects.push({
                    id: `${categoryId}_${subcategory}_${i}`,
                    title: this.generateProjectTitle(subcategory, i),
                    description: this.generateProjectDescription(subcategory),
                    subcategory: subcategory,
                    language: this.getSubcategoryLanguage(subcategory),
                    difficulty: this.getRandomDifficulty(),
                    tags: this.generateProjectTags(categoryId, subcategory),
                    github_url: `https://github.com/example/${categoryId}-${subcategory}-${i}`,
                    demo_url: Math.random() > 0.5 ? `https://demo.example.com/${categoryId}-${subcategory}-${i}` : null,
                    last_updated: this.getRandomDate(),
                    features: this.generateFeatures(subcategory)
                });
            }
        }

        return mockProjects;
    }

    /**
     * Render a project card
     */
    renderProjectCard(project) {
        const languageInfo = this.getLanguageInfo(project.language);
        const difficultyClass = `difficulty-${project.difficulty}`;

        return `
            <article class="project-card ${difficultyClass}" data-project="${project.id}">
                <div class="project-header">
                    <div class="project-language">
                        <span class="language-icon">${languageInfo.icon}</span>
                        <span class="language-name">${languageInfo.name}</span>
                    </div>
                    <div class="project-difficulty">
                        <span class="difficulty-badge">${project.difficulty}</span>
                    </div>
                </div>

                <div class="project-content">
                    <h3 class="project-title">${project.title}</h3>
                    <p class="project-description">${project.description}</p>

                    <div class="project-features">
                        ${project.features.slice(0, 3).map(feature => 
                            `<span class="feature-tag">${feature}</span>`
                        ).join('')}
                    </div>
                </div>

                <div class="project-meta">
                    <div class="project-tags">
                        ${project.tags.slice(0, 4).map(tag => 
                            `<span class="tag">${tag}</span>`
                        ).join('')}
                    </div>
                    <div class="project-date">
                        <span class="last-updated">Updated ${this.formatDate(project.last_updated)}</span>
                    </div>
                </div>

                <div class="project-actions">
                    <a href="${project.github_url}" class="btn btn-outline" target="_blank">
                        <span>GitHub</span>
                        <span class="btn-icon">🔗</span>
                    </a>
                    ${project.demo_url ? `
                        <a href="${project.demo_url}" class="btn btn-primary" target="_blank">
                            <span>Demo</span>
                            <span class="btn-icon">🚀</span>
                        </a>
                    ` : ''}
                </div>
            </article>
        `;
    }

    /**
     * Add interactive features to project cards
     */
    addProjectCardInteractions() {
        document.querySelectorAll('.project-card').forEach(card => {
            // Hover effects
            card.addEventListener('mouseenter', () => {
                card.style.transform = 'translateY(-8px) scale(1.02)';
            });

            card.addEventListener('mouseleave', () => {
                card.style.transform = 'translateY(0) scale(1)';
            });

            // Click to expand details
            card.addEventListener('click', (e) => {
                if (e.target.tagName !== 'A' && e.target.tagName !== 'BUTTON') {
                    this.showProjectDetails(card.dataset.project);
                }
            });
        });
    }

    /**
     * Show detailed project information
     */
    async showProjectDetails(projectId) {
        const project = await this.getProjectDetails(projectId);
        if (!project) return;

        const modal = this.createProjectModal(project);
        document.body.appendChild(modal);

        // Animate modal in
        setTimeout(() => modal.classList.add('active'), 10);

        // Add close handlers
        modal.querySelector('.modal-close').addEventListener('click', () => {
            this.closeProjectModal(modal);
        });

        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                this.closeProjectModal(modal);
            }
        });
    }

    /**
     * Create project details modal
     */
    createProjectModal(project) {
        const modal = document.createElement('div');
        modal.className = 'project-modal';
        modal.innerHTML = `
            <div class="modal-container">
                <div class="modal-header">
                    <h2 class="modal-title">${project.title}</h2>
