                            Live Demo
                        </a>
                    ` : ''}
                </div>
            </div>
        `;

        return modal;
    }

    /**
     * Navigate to category page
     */
    navigateToCategory(categoryId) {
        window.location.href = `/CODE/${categoryId}/`;
    }

    /**
     * Utility methods for generating mock data
     */
    generateProjectTitle(subcategory, index) {
        const titles = {
            sorting: ['Quick Sort Visualizer', 'Merge Sort Implementation', 'Heap Sort Algorithm'],
            searching: ['Binary Search Tree', 'Hash Table Implementation', 'Graph Search Algorithms'],
            frontend: ['React Component Library', 'Vue.js Dashboard', 'Angular Material Design'],
            backend: ['REST API Server', 'GraphQL Endpoint', 'Microservices Architecture'],
            machine_learning: ['Neural Network Classifier', 'Sentiment Analysis Tool', 'Recommendation Engine'],
            ios: ['SwiftUI Weather App', 'Core Data Recipe App', 'ARKit Navigation'],
            android: ['Kotlin Todo App', 'Room Database Example', 'Material Design Gallery']
        };

        const categoryTitles = titles[subcategory] || [`${subcategory.replace('_', ' ')} Project`];
        return categoryTitles[index % categoryTitles.length] || `${subcategory.replace('_', ' ')} Example ${index + 1}`;
    }

    generateProjectDescription(subcategory) {
        const descriptions = {
            sorting: 'A comprehensive implementation with visualization and performance analysis.',
            searching: 'Efficient search algorithm with detailed complexity analysis and examples.',
            frontend: 'Modern, responsive component built with best practices and accessibility.',
            backend: 'Scalable server implementation with comprehensive documentation.',
            machine_learning: 'ML model with training pipeline and evaluation metrics.',
            ios: 'Native iOS app showcasing platform-specific features and design patterns.',
            android: 'Android application following Material Design guidelines.'
        };

        return descriptions[subcategory] || `Professional ${subcategory.replace('_', ' ')} implementation with modern standards.`;
    }

    getSubcategoryLanguage(subcategory) {
        const languageMap = {
            sorting: 'python',
            searching: 'python',
            data_structures: 'cpp',
            frontend: 'javascript',
            backend: 'node',
            machine_learning: 'python',
            ios: 'swift',
            android: 'kotlin',
            unity: 'csharp',
            web_games: 'javascript'
        };

        return languageMap[subcategory] || 'python';
    }

    getLanguageInfo(language) {
        const languages = {
            python: { name: 'Python', icon: '🐍', color: '#3776AB' },
            javascript: { name: 'JavaScript', icon: '⚡', color: '#F7DF1E' },
            typescript: { name: 'TypeScript', icon: '📘', color: '#3178C6' },
            java: { name: 'Java', icon: '☕', color: '#ED8B00' },
            csharp: { name: 'C#', icon: '🔷', color: '#239120' },
            cpp: { name: 'C++', icon: '⚙️', color: '#00599C' },
            swift: { name: 'Swift', icon: '🦉', color: '#FA7343' },
            kotlin: { name: 'Kotlin', icon: '🎯', color: '#7F52FF' },
            rust: { name: 'Rust', icon: '🦀', color: '#000000' },
            go: { name: 'Go', icon: '🐹', color: '#00ADD8' },
            node: { name: 'Node.js', icon: '💚', color: '#339933' }
        };

        return languages[language] || { name: 'Code', icon: '💻', color: '#666666' };
    }

    getRandomDifficulty() {
        const difficulties = ['beginner', 'intermediate', 'advanced'];
        return difficulties[Math.floor(Math.random() * difficulties.length)];
    }

    generateProjectTags(category, subcategory) {
        const baseTags = [category, subcategory];
        const extraTags = ['tutorial', 'example', 'open-source', 'documentation'];
        const randomTags = extraTags.slice(0, Math.floor(Math.random() * 3) + 1);
        return [...baseTags, ...randomTags];
    }

    generateFeatures(subcategory) {
        const featureMap = {
            sorting: ['Visualization', 'Performance Analysis', 'Multiple Algorithms', 'Time Complexity'],
            frontend: ['Responsive Design', 'Accessibility', 'Modern CSS', 'Component Based'],
            backend: ['RESTful API', 'Database Integration', 'Authentication', 'Error Handling'],
            machine_learning: ['Data Preprocessing', 'Model Training', 'Evaluation Metrics', 'Visualization']
        };

        return featureMap[subcategory] || ['Clean Code', 'Documentation', 'Testing', 'Performance'];
    }

    getRandomDate() {
        const start = new Date(2023, 0, 1);
        const end = new Date();
        return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));
    }

    formatDate(date) {
        return new Date(date).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    }

    // Loading and error states
    renderLoadingState() {
        return `
            <div class="loading-state">
                <div class="loading-spinner"></div>
                <p>Loading projects...</p>
            </div>
        `;
    }

    renderEmptyState(categoryId) {
        return `
            <div class="empty-state">
                <div class="empty-icon">📁</div>
                <h3>No Projects Found</h3>
                <p>No projects available in ${categoryId} category yet.</p>
                <button class="btn btn-primary" onclick="window.history.back()">
                    Go Back
                </button>
            </div>
        `;
    }

    renderErrorState() {
        return `
            <div class="error-state">
                <div class="error-icon">⚠️</div>
                <h3>Error Loading Projects</h3>
                <p>Unable to load projects. Please try again later.</p>
                <button class="btn btn-primary" onclick="window.location.reload()">
                    Retry
                </button>
            </div>
        `;
    }

    animateCardsIn(container) {
        const cards = container.querySelectorAll('.category-card, .project-card');
        cards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(20px)';

            setTimeout(() => {
                card.style.transition = 'all 0.3s ease';
                card.style.opacity = '1';
                card.style.transform = 'translateY(0)';
            }, index * 100);
        });
    }
}

// Syntax highlighting utility
class SyntaxHighlighter {
    constructor() {
        this.loadPrismJS();
    }

    async loadPrismJS() {
        if (window.Prism) return;

        // Load Prism.js for syntax highlighting
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://cdnjs.cloudflare.com/ajax/libs/prism/1.24.1/themes/prism-tomorrow.min.css';
        document.head.appendChild(link);

        const script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/prism/1.24.1/components/prism-core.min.js';
        script.onload = () => {
            this.loadLanguageSupport();
        };
        document.head.appendChild(script);
    }

    loadLanguageSupport() {
        const languages = ['javascript', 'python', 'java', 'cpp', 'csharp', 'swift', 'kotlin'];
        languages.forEach(lang => {
            const script = document.createElement('script');
            script.src = `https://cdnjs.cloudflare.com/ajax/libs/prism/1.24.1/components/prism-${lang}.min.js`;
            document.head.appendChild(script);
        });
    }

    highlight(element) {
        if (window.Prism) {
            window.Prism.highlightElement(element);
        }
    }
}

