/**
 * Knowledge Hub - Enhanced Scripts with Proper Path Handling
 * Fixes CSS 404 errors and improves navigation
 */

class KnowledgeHub {
    constructor() {
        this.currentPage = 1;
        this.maxPages = 10;
        this.currentSection = 'home';
        this.theme = localStorage.getItem('theme') || 'auto';
        this.prefersDarkMode = window.matchMedia('(prefers-color-scheme: dark)').matches;
        this.loadedCSS = new Set(); // Track loaded CSS files

        this.initializeApp();
    }

    /**
     * Initialize the entire application
     */
    async initializeApp() {
        try {
            await this.initializeTheme();
            this.initializeEventListeners();
            this.initializeIntersectionObserver();
            this.initializeKeyboardShortcuts();
            this.initializeMobileSupport();

            // Set initial state
            this.updateLastUpdated();
            this.handleInitialRoute();

            console.log('✅ Knowledge Hub initialized successfully');
        } catch (error) {
            console.error('❌ Failed to initialize Knowledge Hub:', error);
        }
    }

    /**
     * Initialize all event listeners
     */
    initializeEventListeners() {
        // Navigation links
        document.querySelectorAll('.nav-link').forEach(link => {
            link.addEventListener('click', this.handleNavigation.bind(this));
        });

        // Theme toggle
        const themeToggle = document.getElementById('theme-toggle');
        if (themeToggle) {
            themeToggle.addEventListener('click', this.toggleTheme.bind(this));
        }

        // Mobile menu toggle
        const menuToggle = document.querySelector('.menu-toggle');
        if (menuToggle) {
            menuToggle.addEventListener('click', this.toggleMobileMenu.bind(this));
        }

        // Search functionality
        this.initializeSearch();

        // Hero action buttons
        document.querySelectorAll('.hero-actions .btn').forEach(btn => {
            const onclick = btn.getAttribute('onclick');
            if (onclick && onclick.includes('loadSection')) {
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    const match = onclick.match(/loadSection\('([^']+)'\)/);
                    if (match) {
                        this.handleSectionNavigation(match[1]);
                    }
                });
            }
        });

        // Scroll handling
        window.addEventListener('scroll', this.handleScroll.bind(this), { passive: true });
        window.addEventListener('resize', this.handleResize.bind(this), { passive: true });
    }

    /**
     * Handle navigation with proper routing
     */
    handleNavigation(event) {
        const link = event.currentTarget;
        const section = link.dataset.section;
        const href = link.getAttribute('href');

        // If it's an external link or has a specific href, let browser handle it
        if (href && (href.startsWith('http') || href.includes('.html'))) {
            return; // Let browser handle normal navigation
        }

        // Handle internal section navigation
        if (section) {
            event.preventDefault();
            this.handleSectionNavigation(section);
        }
    }

    /**
     * Handle section navigation
     */
    async handleSectionNavigation(section) {
        try {
            // Update navigation state
            this.updateActiveNavigation(section);

            // Handle different sections
            switch (section) {
                case 'home':
                    this.scrollToTop();
                    break;
                case 'books':
                    // Navigate to books page
                    window.location.href = './BOOK/index.html';
                    break;
                case 'courses':
                    window.location.href = './COURSES/index.html';
                    break;
                case 'thoughts':
                    window.location.href = './THOUGHTS/index.html';
                    break;
                case 'projects':
                    window.location.href = './PROJECTS/index.html';
                    break;
                default:
                    console.warn('Unknown section:', section);
            }
        } catch (error) {
            console.error('Navigation error:', error);
            this.showErrorMessage(`Failed to navigate to ${section}`);
        }
    }

    /**
     * Update active navigation state
     */
    updateActiveNavigation(section) {
        document.querySelectorAll('.nav-link').forEach(link => {
            link.classList.remove('active');
            if (link.dataset.section === section) {
                link.classList.add('active');
            }
        });
        this.currentSection = section;
    }

    /**
     * Load CSS file dynamically (only if not already loaded)
     */
    async loadCSS(url) {
        if (this.loadedCSS.has(url)) {
            return Promise.resolve();
        }

        return new Promise((resolve, reject) => {
            // Check if file exists first
            fetch(url, { method: 'HEAD' })
                .then(response => {
                    if (!response.ok) {
                        console.warn(`CSS file not found: ${url}`);
                        resolve(); // Don't fail the whole process
                        return;
                    }

                    const link = document.createElement('link');
                    link.rel = 'stylesheet';
                    link.href = url;

                    link.onload = () => {
                        this.loadedCSS.add(url);
                        resolve();
                    };

                    link.onerror = () => {
                        console.warn(`Failed to load CSS: ${url}`);
                        resolve(); // Don't fail the whole process
                    };

                    document.head.appendChild(link);
                })
                .catch(() => {
                    console.warn(`Could not check CSS file: ${url}`);
                    resolve(); // Don't fail the whole process
                });
        });
    }

    /**
     * Initialize search functionality
     */
    initializeSearch() {
        const searchInput = document.getElementById('search-input');
        const searchModal = document.getElementById('search-modal');
        const searchResults = document.getElementById('search-results');

        if (searchInput) {
            searchInput.addEventListener('input', this.debounce(this.handleSearch.bind(this), 300));
        }

        // Global search shortcut
        document.addEventListener('keydown', (e) => {
            if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
                e.preventDefault();
                this.openSearchModal();
            }
            if (e.key === 'Escape') {
                this.closeSearchModal();
            }
        });
    }

    /**
     * Handle search functionality
     */
    handleSearch(event) {
        const query = event.target.value.toLowerCase().trim();
        const resultsContainer = document.getElementById('search-results');

        if (!resultsContainer) return;

        if (!query) {
            resultsContainer.innerHTML = '';
            return;
        }

        // Search in current page content
        const searchableElements = document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, .card-title, .section-title');
        const results = [];

        searchableElements.forEach(element => {
            const text = element.textContent.toLowerCase();
            if (text.includes(query)) {
                results.push({
                    element: element,
                    text: element.textContent.trim(),
                    type: element.tagName.toLowerCase(),
                    score: this.calculateSearchScore(text, query)
                });
            }
        });

        // Sort by relevance
        results.sort((a, b) => b.score - a.score);

        this.displaySearchResults(results, query);
    }

    /**
     * Calculate search relevance score
     */
    calculateSearchScore(text, query) {
        const words = query.split(' ');
        let score = 0;

        words.forEach(word => {
            if (text.includes(word)) {
                score += word.length;
                // Boost score for exact matches
                if (text === word) score += 10;
                // Boost score for beginning matches
                if (text.startsWith(word)) score += 5;
            }
        });

        return score;
    }

    /**
     * Display search results
     */
    displaySearchResults(results, query) {
        const container = document.getElementById('search-results');
        if (!container) return;

        if (results.length === 0) {
            container.innerHTML = `
                <div class="search-empty">
                    <div class="search-empty-icon">🔍</div>
                    <p>No results found for "${query}"</p>
                </div>
            `;
            return;
        }

        container.innerHTML = results.slice(0, 8).map(result => {
            const highlightedText = this.highlightSearchTerms(result.text, query);
            return `
                <div class="search-result" onclick="this.querySelector('.highlight').scrollIntoView({behavior: 'smooth', block: 'center'})">
                    <div class="search-result-icon">${this.getSearchResultIcon(result.type)}</div>
                    <div class="search-result-content">
                        <h4 class="search-result-title">${highlightedText}</h4>
                        <p class="search-result-meta">${result.type.toUpperCase()}</p>
                    </div>
                </div>
            `;
        }).join('');
    }

    /**
     * Highlight search terms in text
     */
    highlightSearchTerms(text, query) {
        const words = query.split(' ').filter(word => word.length > 0);
        let highlightedText = text;

        words.forEach(word => {
            const regex = new RegExp(`(${this.escapeRegex(word)})`, 'gi');
            highlightedText = highlightedText.replace(regex, '<span class="highlight">$1</span>');
        });

        return highlightedText;
    }

    escapeRegex(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    getSearchResultIcon(type) {
        const icons = {
            h1: '📄', h2: '📋', h3: '📝', h4: '📌', h5: '🔖', h6: '🏷️',
            p: '📄', div: '📦', article: '📄', section: '📁'
        };
        return icons[type] || '📄';
    }

    openSearchModal() {
        const modal = document.getElementById('search-modal');
        const searchInput = document.getElementById('search-input');

        if (modal) {
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        }

        if (searchInput) {
            setTimeout(() => searchInput.focus(), 100);
        }
    }

    closeSearchModal() {
        const modal = document.getElementById('search-modal');
        const searchInput = document.getElementById('search-input');
        const searchResults = document.getElementById('search-results');

        if (modal) {
            modal.classList.remove('active');
            document.body.style.overflow = '';
        }

        if (searchInput) {
            searchInput.value = '';
        }

        if (searchResults) {
            searchResults.innerHTML = '';
        }
    }

    /**
     * Theme management
     */
    async initializeTheme() {
        // Set initial theme
        this.applyTheme();

        // Listen for system theme changes
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => {
            this.prefersDarkMode = e.matches;
            if (this.theme === 'auto') {
                this.applyTheme();
            }
        });
    }

    applyTheme() {
        let effectiveTheme;

        if (this.theme === 'auto') {
            effectiveTheme = this.prefersDarkMode ? 'dark' : 'light';
        } else {
            effectiveTheme = this.theme;
        }

        document.documentElement.setAttribute('data-theme', effectiveTheme);

        // Update theme toggle icon
        const themeIcon = document.querySelector('.theme-icon');
        if (themeIcon) {
            const icons = { light: '🌙', dark: '☀️', auto: '🌓' };
            themeIcon.textContent = icons[this.theme];
        }
    }

    toggleTheme() {
        const themes = ['light', 'dark', 'auto'];
        const currentIndex = themes.indexOf(this.theme);
        this.theme = themes[(currentIndex + 1) % themes.length];

        localStorage.setItem('theme', this.theme);
        this.applyTheme();
    }

    /**
     * Mobile support
     */
    initializeMobileSupport() {
        // Touch gesture support
        let touchStartX = 0;
        let touchStartY = 0;

        document.addEventListener('touchstart', (e) => {
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
        }, { passive: true });

        document.addEventListener('touchend', (e) => {
            const touchEndX = e.changedTouches[0].clientX;
            const touchEndY = e.changedTouches[0].clientY;

            const deltaX = touchEndX - touchStartX;
            const deltaY = touchEndY - touchStartY;

            // Swipe detection (minimum 100px, more horizontal than vertical)
            if (Math.abs(deltaX) > 100 && Math.abs(deltaX) > Math.abs(deltaY)) {
                if (deltaX > 0) {
                    // Swipe right - could trigger navigation
                    this.handleSwipeRight();
                } else {
                    // Swipe left - could trigger navigation  
                    this.handleSwipeLeft();
                }
            }
        }, { passive: true });
    }

    handleSwipeRight() {
        // Could implement navigation to previous section
        console.log('Swipe right detected');
    }

    handleSwipeLeft() {
        // Could implement navigation to next section
        console.log('Swipe left detected');
    }

    toggleMobileMenu() {
        const navbar = document.querySelector('.navbar');
        if (navbar) {
            navbar.classList.toggle('mobile-menu-open');
        }
    }

    /**
     * Initialize intersection observer for animations
     */
    initializeIntersectionObserver() {
        const observerOptions = {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        };

        this.observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('animate-in');
                } else {
                    entry.target.classList.remove('animate-in');
                }
            });
        }, observerOptions);

        // Observe all animatable elements
        document.querySelectorAll('.category-card, .feature-card, .floating-card, .content-card').forEach(el => {
            this.observer.observe(el);
        });
    }

    /**
     * Initialize keyboard shortcuts
     */
    initializeKeyboardShortcuts() {
        document.addEventListener('keydown', (e) => {
            // Don't trigger shortcuts when typing in inputs
            if (e.target.matches('input, textarea, [contenteditable]')) return;

            switch(e.key) {
                case 'h':
                    e.preventDefault();
                    this.handleSectionNavigation('home');
                    break;
                case 'b':
                    e.preventDefault();
                    this.handleSectionNavigation('books');
                    break;
                case 'c':
                    e.preventDefault();
                    this.handleSectionNavigation('courses');
                    break;
                case 't':
                    e.preventDefault();
                    this.handleSectionNavigation('thoughts');
                    break;
                case 'p':
                    e.preventDefault();
                    this.handleSectionNavigation('projects');
                    break;
                case '?':
                    e.preventDefault();
                    this.showKeyboardShortcuts();
                    break;
            }
        });
    }

    showKeyboardShortcuts() {
        const shortcuts = [
            { key: 'H', description: 'Home' },
            { key: 'B', description: 'Books' },
            { key: 'C', description: 'Courses' },
            { key: 'T', description: 'Thoughts' },
            { key: 'P', description: 'Projects' },
            { key: 'Cmd/Ctrl + K', description: 'Search' },
            { key: 'Esc', description: 'Close modal' },
            { key: '?', description: 'Show shortcuts' }
        ];

        const shortcutsHtml = shortcuts.map(s => 
            `<div class="shortcut-item"><kbd>${s.key}</kbd><span>${s.description}</span></div>`
        ).join('');

        this.showModal('Keyboard Shortcuts', shortcutsHtml);
    }

    showModal(title, content) {
        // Create modal if it doesn't exist
        let modal = document.getElementById('shortcuts-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'shortcuts-modal';
            modal.className = 'modal';
            modal.innerHTML = `
                <div class="modal-content">
                    <div class="modal-header">
                        <h3 class="modal-title">${title}</h3>
                        <button class="modal-close" onclick="this.closest('.modal').remove()">&times;</button>
                    </div>
                    <div class="modal-body">${content}</div>
                </div>
            `;
            document.body.appendChild(modal);
        }

        modal.style.display = 'flex';
        setTimeout(() => modal.classList.add('active'), 10);
    }

    /**
     * Handle initial route based on URL hash
     */
    handleInitialRoute() {
        const hash = window.location.hash.slice(1);
        if (hash && ['home', 'books', 'courses', 'thoughts', 'projects'].includes(hash)) {
            this.handleSectionNavigation(hash);
        }
    }

    /**
     * Scroll handling
     */
    handleScroll() {
        // Update progress bar
        const scrollProgress = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
        const progressBars = document.querySelectorAll('.progress-bar');
        progressBars.forEach(bar => {
            bar.style.width = `${Math.min(scrollProgress, 100)}%`;
        });

        // Handle navbar on scroll
        const navbar = document.querySelector('.navbar');
        if (navbar) {
            if (window.scrollY > 100) {
                navbar.classList.add('scrolled');
            } else {
                navbar.classList.remove('scrolled');
            }
        }

        // Parallax effect for hero
        const hero = document.querySelector('.hero');
        if (hero && window.scrollY < window.innerHeight) {
            const scroll = window.scrollY;
            hero.style.transform = `translateY(${scroll * 0.5}px)`;
        }
    }

    handleResize() {
        // Close mobile menu on large screens
        if (window.innerWidth > 768) {
            const navbar = document.querySelector('.navbar');
            if (navbar) {
                navbar.classList.remove('mobile-menu-open');
            }
        }
    }

    /**
     * Utility methods
     */
    scrollToTop() {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }

    showErrorMessage(message) {
        console.error(message);

        // Create toast notification
        const toast = document.createElement('div');
        toast.className = 'error-toast';
        toast.innerHTML = `
            <div class="toast-icon">⚠️</div>
            <div class="toast-message">${message}</div>
        `;

        document.body.appendChild(toast);

        setTimeout(() => toast.classList.add('show'), 100);
        setTimeout(() => {
            toast.classList.remove('show');
            setTimeout(() => document.body.removeChild(toast), 300);
        }, 3000);
    }

    updateLastUpdated() {
        const lastUpdatedElements = document.querySelectorAll('#last-updated, .last-updated');
        const now = new Date().toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });

        lastUpdatedElements.forEach(el => {
            el.textContent = now;
        });
    }

    debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }
}

// Global utility functions
function scrollToSection(sectionId) {
    const element = document.getElementById(sectionId);
    if (element) {
        element.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
    }
}

function loadSection(section) {
    if (window.app) {
        window.app.handleSectionNavigation(section);
    }
}

// Initialize when DOM is ready
function initializeApp() {
    window.app = new KnowledgeHub();
    console.log('🚀 Knowledge Hub loaded');
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeApp);
} else {
    initializeApp();
}

